"""Migrated Meridian CRM opportunity_pipeline workflow."""

from typing import Any


def _amount_is_positive(record: dict) -> bool:
    """Evaluate VRL: NVL(AMT,0) > 0."""
    value: Any = record.get("AMT", "")
    if value is None or value == "":
        value = 0

    try:
        return float(value) > 0
    except (TypeError, ValueError):
        return False


def _has_close_date(record: dict) -> bool:
    """Evaluate VRL: CLOSE_DT <> '00000000'."""
    return record.get("CLOSE_DT", "") != "00000000"


def _has_loss_reason(record: dict) -> bool:
    """Evaluate VRL: LOST_RSN <> ''."""
    value = record.get("LOST_RSN", "")
    return isinstance(value, str) and value != ""


def fire(state: str, event: str, record: dict) -> dict:
    """Fire one opportunity_pipeline workflow event."""
    updated_record = dict(record)

    transition = None

    if state == "P" and event == "qualify" and _amount_is_positive(record):
        transition = ("Q", (("set", "STAGE_PCT", "25"), ("audit", "OPP_QUAL")))
    elif state == "Q" and event == "advance":
        transition = ("N", (("set", "STAGE_PCT", "60"),))
    elif state == "N" and event == "close_won" and _has_close_date(record):
        transition = (
            "W",
            (
                ("set", "STAGE_PCT", "100"),
                ("audit", "OPP_WON"),
                ("notify", "won_deal"),
            ),
        )
    elif state == "P" and event == "close_lost" and _has_loss_reason(record):
        transition = ("L", (("set", "STAGE_PCT", "0"), ("audit", "OPP_LOST")))
    elif state == "Q" and event == "close_lost" and _has_loss_reason(record):
        transition = ("L", (("set", "STAGE_PCT", "0"), ("audit", "OPP_LOST")))
    elif state == "N" and event == "close_lost" and _has_loss_reason(record):
        transition = ("L", (("set", "STAGE_PCT", "0"), ("audit", "OPP_LOST")))

    if transition is None:
        return {
            "state": state,
            "record": updated_record,
            "audits": ["WF_NOMATCH"],
            "notifies": [],
            "matched": False,
        }

    resulting_state, actions = transition
    audits: list[str] = []
    notifies: list[str] = []

    for action in actions:
        action_type = action[0]
        if action_type == "set":
            updated_record[action[1]] = action[2]
        elif action_type == "audit":
            audits.append(action[1])
        elif action_type == "notify":
            notifies.append(action[1])

    return {
        "state": resulting_state,
        "record": updated_record,
        "audits": audits,
        "notifies": notifies,
        "matched": True,
    }
